from dataclasses import dataclass

@dataclass(order=True, frozen=True)
class Version:
    major: int
    minor: int
    patch: int

    @classmethod
    def parse(cls, s: str) -> 'Version':
        parts = [int(p) for p in s.strip().lstrip('v').split('.')]
        return cls(parts[0], parts[1], parts[2])

def match_range(v_str: str, constraint: str) -> bool:
    v = Version.parse(v_str)
    if constraint.startswith('^'):
        base = Version.parse(constraint[1:])
        # Caret: >=base and <next-major
        upper = Version(base.major + 1, 0, 0)
        return v >= base and v < upper
    elif constraint.startswith('~'):
        base = Version.parse(constraint[1:])
        # Tilde: >=base and <next-minor
        upper = Version(base.major, base.minor + 1, 0)
        return v >= base and v < upper
    return v == Version.parse(constraint)

