        self.assertTrue(match_range('1.2.3', '^1.2.3'))
        self.assertTrue(match_range('1.9.9', '^1.2.3'))

    def test_caret_upper_bound(self):
        self.assertFalse(match_range('2.0.0', '^1.2.3'))
        self.assertFalse(match_range('2.0.1', '^1.2.3'))

    def test_caret_below(self):
        self.assertFalse(match_range('1.2.2', '^1.2.3'))

    def test_tilde_lower_bound(self):
        self.assertTrue(match_range('1.2.3', '~1.2.3'))
        self.assertTrue(match_range('1.2.9', '~1.2.3'))

    def test_tilde_upper_bound(self):
        self.assertFalse(match_range('1.3.0', '~1.2.3'))
        self.assertFalse(match_range('1.3.1', '~1.2.3'))

    def test_tilde_below(self):
        self.assertFalse(match_range('1.2.2', '~1.2.3'))

    def test_exact(self):
        self.assertTrue(match_range('1.2.3', '1.2.3'))
